# -*- coding: utf-8 -*-
# Выпускает annotations.md из того же списка слайдов, что и колода (ANN, NODES — из build3.py). Запускается через exec().
L = []
A = L.append
total = sum(float(NODES[n]['mins']) for n in NODES)

A('# V8 для самых маленьких: что за лев этот турболев?')
A('## Полный текст доклада · HolyJS 2026 Autumn · 24.10.2026 · Александр Зайцев\n')
A(f'Этот файл — весь доклад целиком: что на каждом слайде, что говорить, что запускать и что отвечать на вопросы. Порядок и нумерация совпадают с колодой `10-slides.pptx` ({len(ANN)} слайдов); тот же текст лежит в заметках докладчика. Файл собирается скриптом `slides-build/build3.py` вместе с колодой, поэтому разойтись они не могут. Хронометраж — {total:g} минуты плюс вопросы.\n')

A('## Доклад в одном абзаце\n')
A('Есть две функции `normalizeUser`, которые делают одно и то же и дают одинаковый результат; отличаются они тремя строками: A всегда кладёт в объект все восемь полей (нет значения — `null`), B добавляет три хвостовых поля только если значение есть. '
  'Из-за этого A создаёт объекты одной **формы**, а B — восьми. Сборка от этого почти не дорожает, зато дорожает каждое **чтение** полей: место кода, которое читает такие объекты, уходит с быстрого пути на общий — в шесть с лишним раз медленнее на функции и почти вдвое по запросам в секунду на сервисе. '
  'Компилятор не спасает: оптимизирующие ярусы V8 *ставят* на одну форму, и с восемью формами ставить не на что. И так было всегда: в 2014-м ставил Crankshaft, в 2017-м — TurboFan, сегодня — Maglev и TurboFan, завтра — Turbolev; налог B одинаков на Node 22 (TurboFan), Node 24 (Maglev + TurboFan) и под флагом Turbolev, ×6.6–6.9. '
  'Формы и записи мест чтения — с 2008 года, старше всех нынешних компиляторов V8. Кто пишет B — не новость: агент по умолчанию пишет B в 30 случаях из 30, а файл из четырёх правил даёт A в 30 из 30.\n')

A('## Как устроен доклад\n')
A('Двенадцать узлов. Каждый узел отвечает на вопрос, которым закончился предыдущий, — этот вопрос написан на тёмном слайде-разделителе и произносится вслух. Узлы 1–6 идут «вправо по вызовам»: от файла до сервера. Узлы 7–10 — тот же путь назад по времени, три эпохи V8: 2014 (full-codegen и Crankshaft), 2017–2022 (байткод, граф Sea of Nodes, Sparkplug), 2023–2027 (Maglev, Turboshaft, Turbolev) — и вывод: ярусы менялись, ставка — нет. Узлы 11–12 — карта целиком и снова первый слайд, который зал теперь читает сам.\n')
A('| # | Узел | мин | Вопрос, которым узел заканчивается |\n|---|---|---|---|')
for n in sorted(NODES):
    A(f'| {n} | {NODES[n]["title"]} | {NODES[n]["mins"]} | {NODES[n]["q"]} |')
A('')
A('**Постоянные элементы слайда.** Сверху зона A (зелёная), снизу зона B (красная) — там, где сравниваются две функции. Справа колонка из пяти «шапок»: форма · чтение · путь · сервер · эпохи. Они пустые (серые) в начале и заполняются по ходу: форма 1 / 8 — в узле 2, чтение MONO / MEGA — в узле 3, путь быстрый / общий — в узле 5, сервер 2302 / 1180 — в узле 6, эпохи быстро / налог — в узле 10. Под шапками мини-карта: двенадцать точек, текущий шаг подсвечен. '
  'Трижды (после узлов 3, 5 и 8) — «передышка»: карта на весь экран на пять секунд и одна фраза.\n')

A('## Словарь — в порядке появления\n')
for t, d in (('форма', 'внутреннее описание объекта в V8: какие поля и в каком порядке добавлены (hidden class; в трейсах — `map`). Объекты, собранные одинаково, делят одно описание. Вводится в узле 2.'),
             ('место чтения', 'точка в коде, где читается поле (`u.plan`). Движок держит при ней память — с какими формами это место уже работало (inline cache). Память у места кода, не у объекта. Узел 3.'),
             ('MONO / POLY / MEGA', 'состояния места чтения: видело одну форму — быстрый путь; 2–4 — перебор короткого списка; 5 и больше — общий путь: поиск по общей таблице движка «форма + имя поля», без встраивания. Сами объекты при этом остаются быстрыми — это не словарный режим. Узел 3.'),
             ('ярус', 'способ исполнения функции: Ignition (интерпретатор) → Sparkplug → Maglev → TurboFan. Чем больше работы функция сделала (вызовы и витки циклов), тем выше ярус; следующий ярус компилируется в фоне, а функция тем временем работает на прежнем. Узел 4.'),
             ('ставка', 'предположение «сюда приходят формы, которые я видел», которое оптимизирующие ярусы (Maglev, TurboFan) вшивают в машинный код: одна форма — одно сравнение, 2–4 — короткий список, 5 и больше — ставки нет, общий путь. Узел 4.'),
             ('деопт', 'деоптимизация: ставка не сыграла, движок выбрасывает оптимизированный код и возвращает функцию в интерпретатор; записи мест чтения сохраняются и дополняются. В нашем трейсе причина — `reason: wrong map` (бывают и другие). Узел 5.'),
             ('R', 'число проходов чтения по объектам в обработке запроса — ручка «прибора побольше»: чем больше R, тем больше разница A/B (+30% при R = 1, ×3 с лишним при R = 20). Узел 6.'),
             ('p99', '99-й перцентиль задержки: хуже отвечает только один запрос из ста. Узел 6.'),
             ('full-codegen и Crankshaft', 'две ступени V8 2010–2017: full-codegen сразу переводил функцию в машинный код (байткода не было), Crankshaft — первый оптимизирующий компилятор, ставил на формы. Удалены в 2017. Узел 7.'),
             ('вектор записей', 'feedback vector: массив при функции, у каждого места чтения свой слот. С 2015–2016 записи мест чтения живут здесь, а не в машинном коде; формат тот же: 1 → 2–4 → мега. Узел 8.'),
             ('Sea of Nodes', 'граф TurboFan: у операций нет жёсткого порядка, их связывают данные и зависимости. Идея Cliff Click (1995). V8 уходит от него: бэкенд уже заменён на Turboshaft. Узел 8.'),
             ('Turboshaft', 'бэкенд TurboFan: с Chrome 120 (2023) — общие фазы, к 2025-му — целиком; обычный граф блоков, из графа делает машинный код, компилирует примерно вдвое быстрее. Узел 9.'),
             ('Turbolev', 'новый верхний ярус V8 вместо TurboFan: граф Maglev сразу в Turboshaft, мимо графа TurboFan. Пока за флагом, срок не объявлен. Узел 9.'),
             ('Homomorphic IC', 'место чтения, у которого 5+ форм с полем на одном и том же месте, держит одну проверку вместо общего пути. В V8 с 15.09.2026, Chrome 156; в Node пока нет. Узел 10.'),
             ('генерация', 'один ответ агента на тикет, в свежей сессии. Узел 10.')):
    A(f'- **{t}** — {d}')
A('')

A('## Числа доклада\n')
A('Все числа, кроме строк «Node 22» (образ node:22-alpine, V8 12.4) и «Homomorphic IC» (d8 15.6, x64, предварительно), — из одного окружения: Docker, `node:24.21.0-alpine` (V8 13.6), `--cpus 2`; прогон `docker/verify.sh` в репозитории issues-memory-research, ветка `v8-talk-verify`, сводка — `docker/results/NUMBERS-alpine-node24-arm64.md`. Важна тенденция, а не третий знак: на другой машине множители будут другими, направление — тем же (на x64 в CI: прибор ×4.4, сервис ×1.7).\n')
A('| Что | Значение |\n|---|---|')
for k, v in (('прибор, проход чтения: A / B', '0.12 / 0.79 мс · ×6.6'), ('форм у A / B', '1 / 8'), ('сборка: if после литерала', '×0.93–1.02'), ('сборка: условный спред', '×1.5–1.7'), ('чтение', '×5.1–5.4'),
             ('весь запрос при R = 1 / 5 / 20 проходах чтения', '+29–31% / ×1.95–1.98 / ×3.1–3.3'), ('доля парсинга в запросе', '65% → 10%'), ('HTTP, запросов в секунду', '2302 / 1180 · ×1.95'), ('HTTP, p50 / p99', '21 → 41 мс / 42 → 82 мс (+95%)'),
             ('без стадии чтения', '+6–10% (if) · +13–18% (спред)'), ('генерации без правил', '30/30 MEGA · 8 форм · 0.80 мс (0.76–0.83)'), ('генерации с правилами', '30/30 MONO · 1 форма · 0.12 мс (0.12–0.13) · ×6.7'), ('битых / некорректных генераций', '0 / 0 из 60'),
             ('порядок полей (две формы)', 'чтение ×1.39–1.52 · 2005 rps (−13%)'), ('лестница ярусов', '505 → 775 → 70 → 38 мс · ×13.5'),
             ('когда функция доходит до Maglev / TurboFan', 'без циклов внутри — около 1000-го / 13 000-го вызова (Maglev 923–1170, TurboFan 13 108–13 601; размер функции ни при чём); с циклом — раньше'), ('A / B под --turbolev', '0.14 / 0.95 мс · ×6.8'), ('A / B на Node 22 (TurboFan без Maglev)', '0.12 / 0.83 мс · ×6.9'), ('Homomorphic IC (предварительно, d8 15.6 x64)', 'B/A ×5.3 → ×4.1'), ('чтение 8 форм против 1 по версиям', 'Node 22 ×3.4 · Node 24 ×2.7'),
             ('delete', '×10 (Node 20) · ×28–29 (Node 22, 24)'), ('try/catch', 'в одном процессе ×2.8–3.0 · в отдельных 14 = 14 мс')):
    A(f'| {k} | {v} |')
A('')

A('## Правила сцены\n')
for r in ('Живое демо одно — запуск готового файла одной командой: `%HaveSameMap` (слайд 2.3). Всё остальное — записи и скрины; их вывод уже стоит на слайдах.',
          'Демо упало — сразу дальше, без второй попытки: нужный вывод уже на слайде.',
          'На сцене ничего не мерить: числа на ноутбуке будут другими, чем на слайдах.',
          'Прибор запускать из папки `v8-experiment/` (там свой `package.json` с `"type": "commonjs"`) или в контейнере `docker/run.sh`; из корня репозитория он падает с `require is not defined`.',
          'Не говорить: «каждый вызов B стоит N вызовов A» (прибор меряет проход чтения, а не вызов); «петля деопта» (откат один, потом стационар); «AI пишет плохой код» (0 некорректных из 60); «в правилах нет кода» (в первом пункте есть пример).',
          'Не называть то, что не перепроверено: числа Turbolev на d8, A/B-эксперимент в Chrome, сроки включения Turbolev (прогноз «Chrome в 2027» — только как свой прогноз). Homomorphic IC — только с пометкой «предварительно, d8 x64».',
          'Не говорить: «--always-turbofan компилирует всё сразу» (на Node 24 функцию берут в оптимизацию не раньше второго вызова; в V8 14+ флага нет); «Sparkplug приходит на ~700-м вызове» (это пакетная компиляция в бенче, без неё — 9-й вызов); «Node 22 без Maglev по умолчанию» (Node 20 и Node 22 с 22.9 собраны без Maglev, `--maglev` там ничего не включает).',
          'Термин вводится один раз, на своём слайде, и раньше него не звучит: в узле 1 слово `map` — только как строка трейса, «улика, не причина».'):
    A(f'- {r}')
A('')

A('---\n\n# Слайд за слайдом\n')
for i, e in enumerate(ANN, 1):
    mins = '' if e['mins'] in ('—', None) else f' · {e["mins"]} мин'
    tag = '' if e['kind'] == 'слайд' else f' · {e["kind"]}'
    A(f'## Слайд {i} · {e["sid"]} · {e["title"]}{mins}{tag}\n')
    A(f'**На экране.** {e["screen"]}\n')
    if e.get('demo'): A(f'**Демо.** {e["demo"]}\n')
    A(f'**Говорим.** {e["speech"]}\n')

A('---\n\n# Приложение: как перепроверить любое число\n')
A('```\ngit clone -b v8-talk-verify https://github.com/Yoshimuro/issues-memory-research\ncd issues-memory-research/v8-experiment\n./docker/run.sh 24 \'bash docker/verify.sh my-run && node docker/report.js docker/out/my-run\'\n```\n')
A('Прогон идёт около 25 минут, строго последовательно; на время прогона машину не нагружать — старт чувствителен к помехам. Результат — `docker/out/my-run/NUMBERS.md`. Тот же прогон на x64 запускается в GitHub Actions (workflow `v8-talk-verify`, вручную), результаты складываются в ветку `v8-talk-results`. Грабли, на которые уже наступили, — в `v8-experiment/PITFALLS.md`.\n')

open(ANN_OUT, 'w', encoding='utf-8').write('\n'.join(L))
print('annotations:', ANN_OUT, len(ANN), 'слайдов,', sum(len(e['speech'].split()) for e in ANN), 'слов речи')
